/* 3mm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "3mm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl))
{
  int i, j;

  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
  for (i = 0; i < nj; i++)
    for (j = 0; j < nm; j++)
      C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
  for (i = 0; i < nm; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("G");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, G[i][j]);
    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use i-k-j loop ordering for all three matrix products so that
     the innermost loop walks contiguous memory (j dimension),
     improving cache locality and SIMD vectorization.
   - Separate zero-initialization from the accumulation loops and
     fuse it per row to reduce stores and improve locality.
   - Add OpenMP parallelization over the outer i-loop of each
     matrix multiplication; each iteration works on a disjoint
     row of the result, so there are no data races.
   - Use temporary row pointers (marked restrict) to minimize
     address recomputation and help the compiler vectorize.
   - Preserve the floating-point accumulation order: for every
     output element the k-loop still runs from 0 to its upper
     bound in ascending order, exactly as in the original code.
*/
static
void kernel_3mm [[gnu::flatten, gnu::noinline]] (int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i;

#pragma scop
  /* E := A*B
     Dimensions:
       A: [0.._PB_NI)[0.._PB_NK)
       B: [0.._PB_NK)[0.._PB_NJ)
       E: [0.._PB_NI)[0.._PB_NJ)
  */
#pragma omp parallel for schedule(static)
  for (i = 0; i < _PB_NI; ++i)
  {
    /* Initialize row i of E to zero. This matches the original
       semantics where E[i][j] was set to 0 before each dot product. */
    for (int j = 0; j < _PB_NJ; ++j)
      E[i][j] = SCALAR_VAL(0.0);

    /* i-k-j ordering:
       - For fixed (i,j) we still iterate k from 0 to _PB_NK-1 in
         increasing order, so the sequence of floating-point
         operations for E[i][j] is unchanged.
       - The innermost j-loop operates on contiguous elements of
         both B[k][j] and E[i][j], improving cache and SIMD use. */
    for (int k = 0; k < _PB_NK; ++k)
    {
      const DATA_TYPE aik = A[i][k];
      const DATA_TYPE * restrict Bk = &B[k][0];
      DATA_TYPE * restrict Ei = &E[i][0];

#pragma GCC ivdep
      for (int j = 0; j < _PB_NJ; ++j)
        Ei[j] += aik * Bk[j];
    }
  }

  /* F := C*D
     Dimensions:
       C: [0.._PB_NJ)[0.._PB_NM)
       D: [0.._PB_NM)[0.._PB_NL)
       F: [0.._PB_NJ)[0.._PB_NL)
  */
#pragma omp parallel for schedule(static)
  for (i = 0; i < _PB_NJ; ++i)
  {
    for (int j = 0; j < _PB_NL; ++j)
      F[i][j] = SCALAR_VAL(0.0);

    for (int k = 0; k < _PB_NM; ++k)
    {
      const DATA_TYPE cik = C[i][k];
      const DATA_TYPE * restrict Dk = &D[k][0];
      DATA_TYPE * restrict Fi = &F[i][0];

#pragma GCC ivdep
      for (int j = 0; j < _PB_NL; ++j)
        Fi[j] += cik * Dk[j];
    }
  }

  /* G := E*F
     Dimensions:
       E: [0.._PB_NI)[0.._PB_NJ)
       F: [0.._PB_NJ)[0.._PB_NL)
       G: [0.._PB_NI)[0.._PB_NL)
  */
#pragma omp parallel for schedule(static)
  for (i = 0; i < _PB_NI; ++i)
  {
    for (int j = 0; j < _PB_NL; ++j)
      G[i][j] = SCALAR_VAL(0.0);

    for (int k = 0; k < _PB_NJ; ++k)
    {
      const DATA_TYPE eik = E[i][k];
      const DATA_TYPE * restrict Fk = &F[k][0];
      DATA_TYPE * restrict Gi = &G[i][0];

#pragma GCC ivdep
      for (int j = 0; j < _PB_NL; ++j)
        Gi[j] += eik * Fk[j];
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;
  int nm = NM;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(E, DATA_TYPE, NI, NJ, ni, nj);
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, NI, NK, ni, nk);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, NK, NJ, nk, nj);
  POLYBENCH_2D_ARRAY_DECL(F, DATA_TYPE, NJ, NL, nj, nl);
  POLYBENCH_2D_ARRAY_DECL(C, DATA_TYPE, NJ, NM, nj, nm);
  POLYBENCH_2D_ARRAY_DECL(D, DATA_TYPE, NM, NL, nm, nl);
  POLYBENCH_2D_ARRAY_DECL(G, DATA_TYPE, NI, NL, ni, nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_3mm (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(E),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(F),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D),
	      POLYBENCH_ARRAY(G));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(G)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(E);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(F);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);
  POLYBENCH_FREE_ARRAY(G);

  return 0;
}
