   - Loop reordering to make the innermost loops traverse the
     contiguous (column) dimension of the row-major arrays.
   - Row-wise initialization of E, F, and G to avoid redundant
     zeroing and to keep hot rows in cache.
   - Local row pointers to reduce address arithmetic and help
     the compiler with vectorization.
   - Optional OpenMP parallelization of the outer i-loops.
   - Use of GCC's ivdep directive on innermost loops to
     encourage auto-vectorization where safe.
*/
static
void kernel_3mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
