  /* E := A * B
     Original order: i, j, k (inner loop had strided access in B).
     New order: i, (initialize row i of E), k, j.
     The innermost loop now walks j, the contiguous dimension for both
     E[i][j] and B[k][j], improving cache locality and SIMD potential. */
  #pragma omp parallel for schedule(static) private(j,k) if(_PB_NI * _PB_NJ * _PB_NK > 1)
  for (i = 0; i < _PB_NI; i++)
    {
      DATA_TYPE *Ei = E[i];

      /* Initialize the whole row of E once. */
      for (j = 0; j < _PB_NJ; ++j)
        Ei[j] = zero;

      for (k = 0; k < _PB_NK; ++k)
        {
          const DATA_TYPE aik = A[i][k];
          const DATA_TYPE *Bk = B[k];

          /* j-loop is over contiguous memory in both Ei and Bk. */
#pragma GCC ivdep
          for (j = 0; j < _PB_NJ; ++j)
            Ei[j] += aik * Bk[j];
        }
    }

