     Same transformation as for E: inner loop walks the contiguous
     j-dimension of F[i][j] and D[k][j]. */
  #pragma omp parallel for schedule(static) private(j,k) if(_PB_NJ * _PB_NL * _PB_NM > 1)
  for (i = 0; i < _PB_NJ; i++)
    {
      DATA_TYPE *Fi = F[i];

      for (j = 0; j < _PB_NL; ++j)
        Fi[j] = zero;

      for (k = 0; k < _PB_NM; ++k)
        {
          const DATA_TYPE cik = C[i][k];
          const DATA_TYPE *Dk = D[k];

#pragma GCC ivdep
          for (j = 0; j < _PB_NL; ++j)
            Fi[j] += cik * Dk[j];
        }
    }

  /* G := E * F
