      F_[i][j] = SCALAR_VAL(0.0);
    }
  }

  /* Step 2: cache- and vectorization-friendly matmul. */
  #pragma omp parallel for private(j,k) schedule(static)
  for (i = 0; i < _PB_NJ; ++i) {
    DATA_TYPE * restrict F_i = F_[i];
    DATA_TYPE * restrict C_i = C_[i];

    for (k = 0; k < _PB_NM; ++k) {
      const DATA_TYPE c_ik = C_i[k];
